/*
 * [演算法說明]
 * 這是擴展歐幾里得演算法 (Extended Euclidean Algorithm) 的標準應用。
 * 對於給定的 A 和 B，求解 AX + BY = gcd(A, B)。
 * 
 * 遞迴關係：
 * 若已知 B*X' + (A % B)*Y' = D
 * 則 A*Y' + B*(X' - (A/B)*Y') = D
 * 因此 X = Y', Y = X' - (A/B)*Y'
 */

#include <iostream>

using namespace std;

typedef long long ll;

ll extended_gcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1; y = 0;
        return a;
    }
    ll x1, y1;
    ll d = extended_gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return d;
}

int main() {
    ll a, b;
    while (cin >> a >> b) {
        ll x, y;
        ll d = extended_gcd(a, b, x, y);
        cout << x << " " << y << " " << d << endl;
    }
    return 0;
}
